input.command:
cat > /tmp/t1.sql <<'EOF'
INSTALL spatial; LOAD spatial;
INSTALL httpfs; LOAD httpfs;
SET geometry_always_xy = true;
SELECT count(*) AS n FROM read_parquet('https://data.source.coop/wri-data-lab/trazofields/trazo3-fields/trazo3_brazil_goias_2024.parquet');
EOF
timeout 300 duckdb -c ".read /tmp/t1.sql" 2>&1 | head -40

cat > /tmp/schema.sql <<'EOF'
INSTALL spatial; LOAD spatial;
INSTALL httpfs; LOAD httpfs;
SET geometry_always_xy = true;
DESCRIBE SELECT * FROM read_parquet('https://data.source.coop/wri-data-lab/trazofields/trazo3-fields/trazo3_brazil_goias_2024.parquet');
EOF
timeout 300 duckdb -c ".read /tmp/schema.sql" 2>&1 | head -120

cat > /tmp/hdr.sql <<'EOF'
INSTALL spatial; LOAD spatial;
INSTALL httpfs; LOAD httpfs;
SET geometry_always_xy = true;
EOF
cat > /tmp/s2.sql <<'EOF'
.read /tmp/hdr.sql
.mode line
DESCRIBE SELECT * FROM read_parquet('https://data.source.coop/tristangruppwri/soft-commodity-infrastructure/facilities/BR_facilities.parquet');
EOF
timeout 300 duckdb -c ".read /tmp/s2.sql" 2>&1 | head -80
